<?php
declare(strict_types=1);
$tab = $protectionRequest['tab']; $overview = $protectionPage['overview']; $record = $protectionPage['review'];
$editing = $protectionRequest['record'] !== ''; $attempt = $protectionAttempt ?? null;
$value = static fn(string $key, mixed $default = ''): mixed => $attempt !== null && array_key_exists($key, $attempt) ? $attempt[$key] : ($record[$key] ?? $default);
$targets = $attempt !== null ? $attempt['targets'] : array_map(static fn(array $row): string => $row['kind'] . ':' . $row['id'], $record['targets'] ?? []);
$people = $value('performer_ids', []); $ready = $overview['enabled'] && $overview['ready'] && app_config('protection.setup_pending', false) !== true;
$labels = ['performers' => 'Collaborators', 'releases' => 'Releases', 'cases' => 'Cases', 'media' => 'Kept offline'];
?>
<div class="protection-workspace" data-protection-workspace>
<section class="protection-intro"><div><span class="admin-kicker">People, permissions & responses</span><h1>Protection & policies</h1><p>Keep private references, review publishing permissions, and respond to reports in one owner workspace.</p></div><a class="admin-button" href="<?= e(base_url('reports/')) ?>" target="_blank" rel="noopener">Open report form ↗</a></section>
<nav class="protection-tabs" aria-label="Protection workspace"><?php foreach ($labels as $key => $label): ?><a class="<?= $tab === $key ? 'active' : '' ?>" <?= $tab === $key ? 'aria-current="page"' : '' ?> href="<?= e(vvx_protection_url($key)) ?>"><?= e($label) ?><span><?= count($overview[$key]) ?></span></a><?php endforeach; ?></nav>
<?php if (!$ready): ?>
<section class="protection-card protection-setup"><span class="admin-kicker">Start with protected delivery</span><h2><?= $overview['enabled'] ? 'Finish protection setup' : 'Enable the protection workspace' ?></h2><p>Managed uploads move into private storage. The website then serves them through current release and case checks. Their previous public upload addresses stop working; saved website links are resolved automatically. Setup first saves a server rule blocking direct uploads, then checks a harmless file through your website address. A host that cannot prove this denial must be configured before activation can finish. Existing cached copies outside this server need their own cache removal.</p><p>This covers files in the saved Media Library. Shipped interface artwork and files hosted elsewhere retain their own addresses. Keep identity documents in your secure document system and save references here.</p><form method="post" action="<?= e(vvx_protection_url($tab)) ?>" data-protection-activate><?= csrf_field() ?><input type="hidden" name="action" value="protection_activate"><input type="hidden" name="config_revision" value="<?= e($overview['config_revision']) ?>"><input type="hidden" name="state_revision" value="<?= e($overview['revision']) ?>"><label class="protection-check"><input type="checkbox" name="confirm_private" value="1" required><span>Move managed uploads into protected storage and check every future media request.</span></label><button class="admin-button primary"><?= $overview['enabled'] ? 'Finish setup' : 'Enable protection' ?></button></form></section>
<?php endif; ?>
<?php if ($tab === 'media' && $ready): ?>
<section class="protection-card"><h2>Media kept offline after a hold</h2><p>Lifting a hold leaves the affected media unavailable until you release the reviewed file here. Then publish any linked drafts separately. Another active case or release always takes priority. This action does not publish a draft.</p>
<div class="protection-records" data-protection-offline><?php foreach ($overview['media'] as $row): ?><article><div><h3><?= e($row['label']) ?></h3><p><?= $row['can_release'] ? 'Ready for a deliberate file release' : 'Still held, or the saved file is missing' ?></p><small>Kept offline <?= e($row['updated_at']) ?></small></div><?php if ($row['can_release']): ?><form method="post" action="<?= e(vvx_protection_url('media')) ?>" data-protection-release-media><?= csrf_field() ?><input type="hidden" name="action" value="protection_media_release"><input type="hidden" name="id" value="<?= e($row['id']) ?>"><input type="hidden" name="revision" value="<?= e($row['revision']) ?>"><input type="hidden" name="state_revision" value="<?= e($overview['revision']) ?>"><label class="protection-check"><input type="checkbox" name="confirm_available" value="1" required><span>I reviewed this file for release.</span></label><button class="admin-button primary">Make media available</button></form><?php endif; ?></article><?php endforeach; ?><?php if ($overview['media'] === []): ?><div class="protection-empty"><h3>No media awaiting release</h3><p>Files kept offline after a hold will appear here for a deliberate review.</p></div><?php endif; ?></div></section>
<?php elseif ($protectionPage['confirmation']): ?><section class="protection-card"><h2>Confirm your identity to open this record</h2><p>Private references and report details require a recent owner confirmation. Your saved records have not changed.</p><a class="admin-button primary" href="<?= e(base_url('admin/?page=security')) ?>">Confirm in Security</a></section>
<?php elseif ($editing && $ready): ?>
<section class="protection-card"><a class="back-link" href="<?= e(vvx_protection_url($tab)) ?>">← All <?= e(strtolower($labels[$tab])) ?></a><div class="protection-section-heading"><div><span class="admin-kicker"><?= $record === null ? 'New record' : e(vvx_protection_status($record['status'], $tab)) ?></span><h2><?= $record === null ? ($tab === 'performers' ? 'Add a collaborator' : 'Add a release') : e($record['label']) ?></h2></div><?php if (!empty($record['hold'])): ?><span class="protection-badge held">Publication hold active</span><?php endif; ?></div>
<?php if ($tab === 'cases'): ?><div class="protection-case-details"><dl><dt>Case number</dt><dd><?= e($record['id']) ?></dd><dt>Category</dt><dd><?= e(ucfirst($record['category'])) ?></dd><dt>Reporter</dt><dd><?= e($record['name']) ?> · <?= e($record['email']) ?></dd><?php if ($record['url'] !== ''): ?><dt>Reported address</dt><dd><?= e($record['url']) ?></dd><?php endif; ?></dl><h3>Report details</h3><p class="protection-preserve"><?= e($record['description']) ?></p></div><?php endif; ?>
<form method="post" action="<?= e(vvx_protection_url($tab, $protectionRequest['record'])) ?>" data-protection-editor><?= csrf_field() ?><input type="hidden" name="action" value="<?= $tab === 'performers' ? 'protection_performer_save' : ($tab === 'releases' ? 'protection_release_save' : 'protection_case_action') ?>"><input type="hidden" name="id" value="<?= e((string) $value('id', '')) ?>"><input type="hidden" name="revision" value="<?= e((string) $value('revision', 'new')) ?>"><input type="hidden" name="content_revision" value="<?= e((string) ($attempt['content_revision'] ?? $protectionPage['withdrawal']['revision'] ?? '')) ?>">
<?php if ($tab !== 'cases'): ?><div class="protection-grid"><label><?= $tab === 'performers' ? 'Display name' : 'Release title' ?><input name="label" maxlength="160" required value="<?= e((string) $value('label')) ?>"></label><div class="protection-field"><label for="protectionStatus">Status</label><select id="protectionStatus" name="status"><?php foreach (($tab === 'performers' ? ['active' => 'Active', 'inactive' => 'Inactive'] : ['draft' => 'Draft · hold linked content', 'active' => 'Approved', 'revoked' => 'Revoked · hold linked content']) as $key => $label): ?><option value="<?= e($key) ?>" <?= $value('status', $tab === 'performers' ? 'active' : 'draft') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div></div>
<label><?= $tab === 'performers' ? 'Private document reference' : 'Private release reference' ?><input name="document_reference" maxlength="1500" value="<?= e((string) $value('document_reference')) ?>"><small>Use a reference in your secure document system. Do not enter an identity document, payment number or password.</small></label>
<?php if ($tab === 'performers'): ?><label>Last reviewed on<input type="date" name="reviewed_on" value="<?= e((string) $value('reviewed_on')) ?>"></label><?php else: ?>
<div class="protection-field"><label for="protectionPeople">Collaborators</label><select id="protectionPeople" name="performer_ids[]" multiple size="4"><?php foreach ($overview['performers'] as $person): ?><option value="<?= e($person['id']) ?>" <?= in_array($person['id'], $people, true) ? 'selected' : '' ?>><?= e($person['label']) ?><?= $person['status'] !== 'active' ? ' · inactive' : '' ?></option><?php endforeach; ?></select><small>Approval requires at least one active collaborator.</small></div><label>Approval expires after this date (UTC)<input type="date" name="expires_on" value="<?= e((string) $value('expires_on')) ?>"><small>Leave blank only when your saved release has no expiration. Expired approvals hold linked content automatically.</small></label><label class="protection-check"><input type="checkbox" name="consent_reviewed" value="1" <?= $value('consent_reviewed', false) ? 'checked' : '' ?>><span>I reviewed the saved consent and permissions for these collaborators and linked items.</span></label>
<?php endif; ?><label>Private notes<textarea name="notes" rows="4" maxlength="4000"><?= e((string) $value('notes')) ?></textarea></label>
<?php else: ?><div class="protection-field"><label for="protectionDecision">Case action</label><select id="protectionDecision" name="decision"><?php foreach (['review' => 'Record private review', 'request_reply' => 'Request a reporter reply', 'respond' => 'Add a response', 'takedown' => 'Withdraw linked content', 'reinstate' => 'Lift this hold · leave content offline', 'close' => 'Close case · keep any hold'] as $key => $label): if ($key === 'reinstate' && !$record['hold']) continue; ?><option value="<?= e($key) ?>" <?= $value('decision', 'review') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><label>Private decision notes<textarea name="message" rows="4" maxlength="4000" required><?= e((string) $value('message')) ?></textarea></label><label>Response to the reporter<textarea name="public_message" rows="4" maxlength="4000"><?= e((string) $value('public_message')) ?></textarea><small>Required for a response, withdrawal, reinstatement or closure. The reporter reads it with their case access key; this action does not send an email.</small></label><?php endif; ?>
<?php if ($tab !== 'performers'): ?><div class="protection-field"><label for="protectionTargets">Linked publications and media</label><select id="protectionTargets" name="targets[]" multiple size="7"><?php foreach ($protectionPage['choices'] as $choice): ?><option value="<?= e($choice['value']) ?>" <?= in_array($choice['value'], $targets, true) ? 'selected' : '' ?>><?= e($choice['label']) ?></option><?php endforeach; ?></select><small>Choose up to 20 saved items. A case changes these links when you choose Withdraw linked content. Other case actions preserve the existing links.</small></div><?php endif; ?>
<?php if ($record !== null && $protectionPage['withdrawal']['items'] !== []): ?><details class="protection-withdrawal"><summary>Content kept offline when a hold is lifted (<?= count($protectionPage['withdrawal']['items']) ?>)</summary><p>Approval after a hold, collaborator reactivation, or case reinstatement sets these current items to draft or disabled. Review and publish them separately. A newer edit makes this form expire.</p><ul><?php foreach ($protectionPage['withdrawal']['items'] as $item): ?><li><?= e(vvx_protection_kind($item['kind']) . ' · ' . $item['title']) ?></li><?php endforeach; ?></ul></details><?php endif; ?>
<div class="protection-form-actions"><button class="admin-button primary"><?= $tab === 'performers' ? 'Save collaborator' : ($tab === 'releases' ? 'Save release' : 'Save case decision') ?></button><a class="admin-button" href="<?= e(vvx_protection_url($tab)) ?>">Back to list</a></div></form></section>
<?php if ($record !== null): ?><section class="protection-card"><h2>Saved activity</h2><p>Saved decisions remain in this record. Private notes are visible only in this owner review.</p><ol class="protection-history"><?php foreach (array_reverse($record['events']) as $event): ?><li><div><strong><?= e(ucfirst(str_replace('_', ' ', $event['type']))) ?></strong><time><?= e($event['at']) ?></time></div><p class="protection-preserve"><?= e($event['message']) ?></p><?php if ($event['public_message'] !== ''): ?><div class="protection-public-response"><strong>Reporter response</strong><p class="protection-preserve"><?= e($event['public_message']) ?></p></div><?php endif; ?></li><?php endforeach; ?></ol></section><?php endif; ?>
<?php elseif ($tab !== 'media'): ?><section class="protection-card"><div class="protection-section-heading"><div><h2><?= e($labels[$tab]) ?></h2><p><?= $tab === 'performers' ? 'Save collaborator references and review dates. Marking a collaborator inactive holds their linked releases.' : ($tab === 'releases' ? 'Each release binds the saved collaborators and media you reviewed. A draft, revocation, expiration or inactive collaborator holds linked content.' : 'Reports start in the public form. A report records a request; the owner decides whether to withdraw linked content.') ?></p></div><?php if ($tab !== 'cases' && $ready): ?><a class="admin-button primary" href="<?= e(vvx_protection_url($tab, 'new')) ?>"><?= $tab === 'performers' ? 'Add collaborator' : 'Add release' ?></a><?php endif; ?></div>
<div class="protection-records" data-protection-list><?php foreach ($overview[$tab] as $row): ?><article><div><h3><a href="<?= e(vvx_protection_url($tab, $row['id'])) ?>"><?= e($row['label']) ?></a></h3><p><?= e(vvx_protection_status($row['status'], $tab)) ?><?= $row['hold'] ? ' · publication hold active' : '' ?></p><small>Updated <?= e($row['updated_at']) ?></small></div><a class="admin-button" href="<?= e(vvx_protection_url($tab, $row['id'])) ?>">Review</a></article><?php endforeach; ?><?php if ($overview[$tab] === []): ?><div class="protection-empty"><h3>No <?= e(strtolower($labels[$tab])) ?> saved yet</h3><p><?= $tab === 'cases' ? 'New reports will appear here for owner review.' : 'Start with a clearly named record and keep the source documents in your secure document system.' ?></p></div><?php endif; ?></div><p class="protection-limit"><?= count($overview[$tab]) ?> of <?= (int) $overview['limits'][$tab] ?> saved records · Up to 100 activity entries per record. Existing records are never silently removed.</p></section><?php endif; ?>
</div>
